<template>
 <div class="management-page rental-page">
  <span class="page-kicker">HOME OPERATIONS</span><div class="page-heading"><h1 class="page-title">Rent & operations</h1><button class="button button-secondary" :disabled="loading||busy" @click="load">Refresh</button></div>
  <p class="lead">Manage rent, maintenance, leases, and property viewings using your permitted access.</p>
  <StatusMessage :message="error" error :retry="!busy" @retry="load"/><StatusMessage :message="success"/>
  <nav class="rental-tabs" aria-label="Rental workflows"><button v-for="tab in tabs" :key="tab.key" v-show="allowed(tab)" class="button" :class="{ 'button-secondary':section!==tab.key }" @click="select(tab.key)">{{ tab.label }}</button></nav>
  <section class="panel" v-if="section==='payments'">
   <div class="section-heading"><div><h2 class="section-title">Rent tracking</h2><p class="muted">Schedules, generated charges, receipts, and reconciliation.</p></div><button v-if="canManage('RENT_MANAGE')" class="button" @click="showSchedule=!showSchedule">{{ showSchedule?'Close':'Add rent schedule' }}</button></div>
   <form v-if="showSchedule&&canManage('RENT_MANAGE')" class="rental-form" @submit.prevent="saveSchedule"><label class="field">Flat<small class="field-hint">Choose the flat for this record.</small><select v-model="schedule.flatId" class="select-input" required><option value="" disabled>Select a flat</option><option v-for="flat in flats" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select></label><Input name="rentAmount" label="Monthly amount" v-model="schedule.amount" type="number" min="0.01" step="0.01" required/><Input name="rentDueDay" label="Due day" v-model="schedule.dueDay" type="number" min="1" max="31" required/><Input name="rentStartPeriod" label="Start period (YYYY-MM)" v-model="schedule.startPeriod" pattern="[0-9]{4}-[0-9]{2}" required/><Input name="rentEndPeriod" label="End period (optional)" v-model="schedule.endPeriod" pattern="[0-9]{4}-[0-9]{2}"/><button class="button" :disabled="busy">Save schedule</button></form>
   <form v-if="can('RENT_MANAGE')" class="rental-inline-form" @submit.prevent="generate"><Input name="generatePeriod" label="Generate charges for (YYYY-MM)" v-model="period" pattern="[0-9]{4}-[0-9]{2}" required/><button class="button button-secondary" :disabled="busy">Generate rent</button></form>
   <h3 v-if="schedules.length" class="section-title">Recurring schedules</h3><div v-if="schedules.length" class="table-wrap"><table class="data-table"><thead><tr><th>Flat</th><th>Monthly rent</th><th>Due day</th><th>Period</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in schedules" :key="row.id"><td>{{ flatName(row.flatId) }}</td><td>{{ money(row.amount) }}</td><td>{{ row.dueDay }}</td><td>{{ row.startPeriod }} – {{ row.endPeriod||'Ongoing' }}</td><td>{{ row.active?'Active':'Inactive' }}</td><td><button v-if="canManage('RENT_MANAGE')" class="link-button" @click="toggleSchedule(row)">{{ row.active?'Pause':'Resume' }}</button></td></tr></tbody></table></div><div v-if="loading" role="status" class="body-text">Loading rent records...</div><div v-else class="table-wrap"><table v-if="items.length" class="data-table"><thead><tr><th>Flat</th><th>Period / amount</th><th>Status</th><th>Paid / balance</th><th>Receipts</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{ flatName(row.flatId) }}</td><td>{{ row.details.period }} · {{ money(row.details.amount) }}</td><td>{{ row.status }}</td><td>{{ money(row.amountPaid) }} / {{ money(row.balance) }}</td><td><button class="link-button" @click="selectPayment(row)">View / add receipt</button></td></tr></tbody></table><p v-else class="empty">No rent charges found.</p></div>
   <div v-if="selectedPayment" class="panel rental-detail"><div class="section-heading"><h3 class="section-title">Receipts · {{ flatName(selectedPayment.flatId) }}</h3><button class="link-button" @click="selectedPayment=null">Close</button></div><p>Remaining balance: <strong>{{ money(selectedPayment.balance) }}</strong></p><form v-if="canManage('RENT_MANAGE')&&selectedPayment.balance>0" class="rental-inline-form" @submit.prevent="recordReceipt"><Input name="receiptAmount" label="Amount received" v-model="receipt.amount" type="number" min="0.01" :max="selectedPayment.balance" step="0.01" required/><Input name="receiptReference" label="Receipt reference" v-model="receipt.reference" maxlength="120" required/><Input name="receiptDate" label="Received date" v-model="receipt.receivedAt" type="date" :max="today" required/><button class="button" :disabled="busy">Record receipt</button></form><div v-for="r in receipts" :key="r.id" class="rental-row"><div><span>{{ money(r.amount) }} · {{ r.reference }} · {{ r.receivedAt }} · {{ r.reconciled?'Reconciled':'Pending' }}</span><form v-if="canManage('RENT_MANAGE')&&!r.reconciled" class="rental-inline-form" @submit.prevent="reconcile(r)"><Input :name="'statement-ref-'+r.id" label="Statement reference" v-model="reconciliation[r.id].reference" maxlength="120" required/><Input :name="'statement-amount-'+r.id" label="Statement amount" v-model="reconciliation[r.id].amount" type="number" min="0.01" step="0.01" required/><button class="button button-secondary" :disabled="busy">Match statement</button></form></div></div></div>
  </section>
  <section class="panel" v-else-if="section==='maintenance'">
   <div class="section-heading"><div><h2 class="section-title">Maintenance requests</h2><p class="muted">Track priority, assignment, work progress, and closure.</p></div><button v-if="canManage('MAINTENANCE_CREATE')" class="button" @click="showCreate=!showCreate">{{ showCreate?'Close':'New request' }}</button></div>
   <form v-if="showCreate&&canManage('MAINTENANCE_CREATE')" class="rental-form" @submit.prevent="create"><label class="field">Flat<small class="field-hint">Choose the flat for this record.</small><select v-model="draft.flatId" class="select-input" required><option value="" disabled>Select a flat</option><option v-for="flat in flats" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select></label><Input name="maintenanceSummary" label="Summary" v-model="draft.summary" maxlength="160" required/><label class="field">Description<textarea v-model="draft.description" class="text-input" maxlength="2000" required></textarea></label><label class="field">Priority<small class="field-hint">Choose the urgency for this request.</small><select v-model="draft.priority" class="select-input"><option>LOW</option><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select></label><button class="button" :disabled="busy">Submit request</button></form>
   <div v-if="loading" role="status" class="body-text">Loading requests...</div><div v-else class="rental-cards"><article v-for="row in items" :key="row.id" class="rental-card"><div class="section-heading"><div><strong>{{ row.details.summary }}</strong><span class="muted">{{ flatName(row.flatId) }} · {{ row.details.priority }} priority</span></div><span class="status">{{ row.status }}</span></div><p>{{ row.details.description }}</p><p v-if="row.details.assignedTo" class="muted">Assigned to {{ row.details.assignedTo }}</p><p v-if="row.details.closureDetails">Resolution: {{ row.details.closureDetails }}</p><div v-if="canManage('MAINTENANCE_MANAGE')&&row.status!=='CLOSED'" class="rental-actions"><Input :name="'assign-'+row.id" label="Assign to" v-model="assignments[row.id]" maxlength="120"/><button class="button button-secondary" @click="updateMaintenance(row,{assignedTo:assignments[row.id]||''})">Save assignment</button><label v-if="row.status==='OPEN'" class="field">Priority<small class="field-hint">Choose the urgency for this request.</small><select v-model="priorities[row.id]" class="select-input"><option>LOW</option><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select></label><button v-if="row.status==='OPEN'" class="button button-secondary" @click="updateMaintenance(row,{priority:priorities[row.id]||row.details.priority})">Save priority</button><Input v-if="['OPEN','IN_PROGRESS'].includes(row.status)" :name="'progress-'+row.id" label="Progress note" v-model="progressNotes[row.id]" maxlength="2000"/><button v-if="['OPEN','IN_PROGRESS'].includes(row.status)" class="button button-secondary" @click="addProgress(row)">Add update</button><button v-if="row.status==='OPEN'&&row.details.assignedTo" class="button button-secondary" @click="updateMaintenance(row,{status:'IN_PROGRESS'})">Start work</button><Input v-if="['OPEN','IN_PROGRESS'].includes(row.status)" :name="'closure-'+row.id" label="Resolution details" v-model="closures[row.id]" maxlength="2000"/><button v-if="['OPEN','IN_PROGRESS'].includes(row.status)" class="button" @click="updateMaintenance(row,{status:'RESOLVED',closureDetails:closures[row.id]||''})">Resolve</button><button v-if="row.status==='RESOLVED'" class="button" @click="updateMaintenance(row,{status:'CLOSED'})">Close request</button></div><details><summary>Progress history</summary><button class="link-button" @click="loadProgress(row)">Load progress</button><p v-for="p in progress[row.id]||[]" :key="p.id">{{ date(p.createdAt) }} · {{ p.status }} · {{ p.note }}</p></details></article><p v-if="!items.length" class="empty">No maintenance requests found.</p></div>
  </section>
  <section class="panel" v-else-if="section==='leases'">
   <div class="section-heading"><div><h2 class="section-title">Lease renewals & move-outs</h2><p class="muted">Prepare offers, collect tenant responses, and finalize outcomes.</p></div><button v-if="canManage('LEASE_MANAGE')" class="button" @click="showCreate=!showCreate">{{ showCreate?'Close':'Start workflow' }}</button></div>
   <form v-if="showCreate&&canManage('LEASE_MANAGE')" class="rental-form" @submit.prevent="create"><label class="field">Flat<small class="field-hint">Choose the flat for this record.</small><select v-model="draft.flatId" class="select-input" required><option value="" disabled>Select a flat</option><option v-for="flat in flats" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select></label><label class="field">Workflow<small class="field-hint">Choose renewal or move-out.</small><select v-model="draft.action" class="select-input"><option value="RENEWAL">Renewal</option><option value="MOVE_OUT">Move-out</option></select></label><Input name="leaseEndDate" label="Current lease end date" v-model="draft.leaseEndDate" type="date" required/><template v-if="draft.action==='RENEWAL'"><Input name="renewalStartDate" label="Renewal start date" v-model="draft.renewalStartDate" type="date" required/><Input name="renewalEndDate" label="Renewal end date" v-model="draft.renewalEndDate" type="date" required/><Input name="leaseRent" label="Rent amount" v-model="draft.rentAmount" type="number" min="0.01" step="0.01" required/><Input name="securityDeposit" label="Security deposit" v-model="draft.securityDeposit" type="number" min="0" step="0.01" required/></template><Input v-else name="moveOutDate" label="Planned move-out date" v-model="draft.moveOutDate" type="date" required/><label class="field">Notes<textarea v-model="draft.notes" class="text-input" maxlength="2000"></textarea></label><button class="button" :disabled="busy">Create workflow</button></form>
   <div v-if="loading" role="status" class="body-text">Loading lease workflows...</div><div v-else class="rental-cards"><article v-for="row in items" :key="row.id" class="rental-card"><div class="section-heading"><div><strong>{{ row.details.action==='RENEWAL'?'Renewal':'Move-out' }} · {{ flatName(row.flatId) }}</strong><span class="muted">Lease ends {{ row.details.leaseEndDate }}</span></div><span class="status">{{ row.status }}</span></div><p v-if="row.details.tenantResponseNotes">Tenant response: {{ row.details.tenantResponseNotes }}</p><p v-if="row.details.renewalEndDate">Proposed term: {{ row.details.renewalStartDate }} – {{ row.details.renewalEndDate }} · {{ money(row.details.rentAmount) }}</p><div class="rental-actions"><template v-if="canManage('LEASE_MANAGE')"><button v-if="row.status==='DRAFT'&&row.details.action==='RENEWAL'" class="button" @click="updateLease(row,{status:'RENEWAL_OFFERED'})">Send renewal offer</button><button v-if="row.status==='DRAFT'&&row.details.action==='MOVE_OUT'" class="button" @click="updateLease(row,{status:'MOVE_OUT_STARTED'})">Start move-out</button><button v-if="row.status==='RENEWAL_ACCEPTED'" class="button" @click="finalizeRenewal(row)">Finalize renewal</button><template v-if="row.status==='RENEWAL_DECLINED'"><Input :name="'moveout-date-'+row.id" label="Planned move-out date" v-model="moveOutDates[row.id]" type="date" required/><button class="button button-secondary" @click="startMoveoutAfterDecline(row)">Start move-out</button></template><template v-if="row.status==='MOVE_OUT_CONFIRMED'"><Input :name="'actual-'+row.id" label="Actual move-out date" v-model="leaseFinalize[row.id].actualMoveOutDate" type="date"/><Input :name="'inspection-'+row.id" label="Inspection date" v-model="leaseFinalize[row.id].inspectionDate" type="date"/><Input :name="'deposit-'+row.id" label="Deposit settlement" v-model="leaseFinalize[row.id].depositSettlementAmount" type="number" min="0" step="0.01"/><Input :name="'final-notes-'+row.id" label="Finalization notes" v-model="leaseFinalize[row.id].finalizationNotes"/><button class="button" @click="finalizeMoveOut(row)">Finalize move-out</button></template></template><template v-if="can('LEASE_VIEW','OWN_FLATS')||can('LEASE_VIEW','SELF')"><Input v-if="['RENEWAL_OFFERED','MOVE_OUT_STARTED'].includes(row.status)" :name="'tenant-notes-'+row.id" label="Response notes (optional)" v-model="tenantNotes[row.id]" maxlength="1000"/><button v-if="row.status==='RENEWAL_OFFERED'" class="button button-secondary" @click="tenantResponse(row,'RENEWAL_ACCEPTED')">Accept renewal</button><button v-if="row.status==='RENEWAL_OFFERED'" class="button button-secondary" @click="tenantResponse(row,'RENEWAL_DECLINED')">Decline renewal</button><button v-if="row.status==='MOVE_OUT_STARTED'" class="button button-secondary" @click="tenantResponse(row,'MOVE_OUT_CONFIRMED')">Confirm move-out</button></template></div></article><p v-if="!items.length" class="empty">No lease workflows found.</p></div>
  </section>
  <section class="panel" v-else>
   <div class="section-heading"><div><h2 class="section-title">Viewing availability & bookings</h2><p class="muted">Publish slots, book, cancel, reschedule, or reopen availability.</p></div><button v-if="canManage('VIEWING_MANAGE')" class="button" @click="showCreate=!showCreate">{{ showCreate?'Close':'Add viewing slot' }}</button></div>
   <form v-if="showCreate&&canManage('VIEWING_MANAGE')" class="rental-form" @submit.prevent="create"><label class="field">Flat<small class="field-hint">Choose the flat for this record.</small><select v-model="draft.flatId" class="select-input" required><option value="" disabled>Select a flat</option><option v-for="flat in flats" :key="flat.flatId" :value="flat.flatId">{{ flat.flatNumber }}</option></select></label><Input name="viewingSlot" label="Date and time with timezone" v-model="draft.slot" type="datetime-local" required/><Input name="viewingNotes" label="Notes" v-model="draft.notes" maxlength="500"/><button class="button" :disabled="busy">Publish slot</button></form>
   <div v-if="loading" role="status" class="body-text">Loading viewings...</div><div v-else class="rental-cards"><article v-for="row in items" :key="row.id" class="rental-card"><div class="section-heading"><div><strong>{{ flatName(row.flatId) }} · {{ date(row.details.slot) }}</strong><span class="muted">{{ row.details.notes||'Viewing slot' }}</span></div><span class="status">{{ row.status }}</span></div><div class="rental-actions"><button v-if="row.status==='AVAILABLE'&&can('VIEWING_BOOK','OWN_FLATS')" class="button" @click="viewingAction(row,'book',{version:row.version,bookingNotes:''})">Book viewing</button><button v-if="['AVAILABLE','BOOKED'].includes(row.status)&&(canManage('VIEWING_MANAGE')||(can('VIEWING_BOOK','OWN_FLATS')&&row.bookedByCurrentUser))" class="button button-secondary" @click="startCancel(row)">Cancel</button><button v-if="['AVAILABLE','BOOKED'].includes(row.status)&&(canManage('VIEWING_MANAGE')||(can('VIEWING_BOOK','OWN_FLATS')&&row.bookedByCurrentUser))" class="button button-secondary" @click="startReschedule(row)">Reschedule</button><button v-if="row.status==='CANCELLED'&&canManage('VIEWING_MANAGE')" class="button button-secondary" @click="viewingAction(row,'reopen',{version:row.version})">Reopen slot</button></div><form v-if="cancelledId===row.id" class="rental-inline-form" @submit.prevent="confirmCancel(row)"><Input :name="'cancel-reason-'+row.id" label="Cancellation reason" v-model="cancelReasons[row.id]" maxlength="500" required/><button class="button button-danger" :disabled="busy">Confirm cancellation</button><button type="button" class="link-button" @click="cancelledId=null">Keep booking</button></form><form v-if="reschedulingId===row.id" class="rental-inline-form" @submit.prevent="confirmReschedule(row)"><Input :name="'new-slot-'+row.id" label="New viewing time" v-model="reschedules[row.id].slot" type="datetime-local" required/><Input :name="'reschedule-reason-'+row.id" label="Reason (optional)" v-model="reschedules[row.id].reason" maxlength="500"/><button class="button" :disabled="busy">Save new time</button><button type="button" class="link-button" @click="reschedulingId=null">Keep current time</button></form><details v-if="row.details.bookingHistory"><summary>Booking history</summary><p v-for="(h,index) in row.details.bookingHistory" :key="index">{{ h.action }} · {{ date(h.at) }}<span v-if="h.reason"> · {{ h.reason }}</span></p></details></article><p v-if="!items.length" class="empty">No viewing slots found.</p></div>
  </section>
 </div>
</template>
<script>
import access from '../util/access-mixin';import Input from '../components/forms/Input.vue';import StatusMessage from '../components/StatusMessage.vue';import {api,errorMessage} from '../services/api';
const today=()=>new Date().toISOString().slice(0,10),period=()=>today().slice(0,7);
export default {mixins:[access],components:{Input,StatusMessage},data:()=>({section:'payments',loading:false,busy:false,error:'',success:'',items:[],flats:[],schedules:[],showCreate:false,showSchedule:false,selectedPayment:null,cancelledId:null,reschedulingId:null,cancelReasons:{},reschedules:{},receipts:[],reconciliation:{},tenantNotes:{},moveOutDates:{},progress:{},assignments:{},priorities:{},progressNotes:{},closures:{},leaseFinalize:{},draft:{flatId:'',summary:'',description:'',priority:'NORMAL',action:'RENEWAL',leaseEndDate:'',renewalStartDate:'',renewalEndDate:'',rentAmount:'',securityDeposit:'',moveOutDate:'',notes:'',slot:''},schedule:{flatId:'',amount:'',dueDay:1,startPeriod:period(),endPeriod:''},receipt:{amount:'',reference:'',receivedAt:today()},period:period(),today:today()}),computed:{tabs(){return[{key:'payments',label:'Rent',permission:'RENT_VIEW'},{key:'maintenance',label:'Maintenance',permission:'MAINTENANCE_VIEW'},{key:'leases',label:'Leases',permission:'LEASE_VIEW'},{key:'viewings',label:'Viewings',permission:'VIEWING_VIEW'}].filter(t=>this.can(t.permission)||this.can(t.permission,'OWN_FLATS')||this.can(t.permission==='MAINTENANCE_VIEW'?'MAINTENANCE_CREATE':t.permission==='VIEWING_VIEW'?'VIEWING_BOOK':t.permission==='LEASE_VIEW'?'LEASE_MANAGE':'RENT_MANAGE'));}},created(){this.section=this.tabs.length?this.tabs[0].key:'payments';this.load();},methods:{allowed(tab){return this.tabs.some(t=>t.key===tab.key)},canManage(permission){return this.can(permission)||this.can(permission,'OWN_FLATS')},async select(key){this.section=key;this.showCreate=false;this.selectedPayment=null;await this.load()},async load(){if(!this.tabs.length)return;this.loading=true;this.error='';try{const needsFlats=(this.section==='payments'&&this.canManage('RENT_MANAGE'))||(this.section==='maintenance'&&this.canManage('MAINTENANCE_CREATE'))||(this.section==='leases'&&this.canManage('LEASE_MANAGE'))||(this.section==='viewings'&&this.canManage('VIEWING_MANAGE'));const [rows,flats,schedules]=await Promise.all([api.rental(this.section),needsFlats&&this.can('FLAT_VIEW')?api.all('flats'):Promise.resolve([]),this.section==='payments'&&this.canManage('RENT_VIEW')?api.rentSchedules():Promise.resolve([])]);this.items=rows;const user=this.$store.state.session.user;if(needsFlats)this.flats=flats.length?flats:((user&&user.flatIds)||[]).map(id=>({flatId:id,flatNumber:id}));this.schedules=schedules;for(const row of rows){if(this.section==='maintenance'){this.assignments[row.id]=row.details.assignedTo||'';this.priorities[row.id]=row.details.priority||'NORMAL';this.progressNotes[row.id]='';this.closures[row.id]=row.details.closureDetails||''}if(this.section==='leases'&&!this.leaseFinalize[row.id])this.leaseFinalize[row.id]={actualMoveOutDate:today(),inspectionDate:today(),depositSettlementAmount:'0',finalizationNotes:''}}}catch(e){this.error=errorMessage(e)}finally{this.loading=false}},flatName(id){return (this.flats.find(f=>f.flatId===id)||{}).flatNumber||id||'—'},money(value){return new Intl.NumberFormat(undefined,{style:'currency',currency:'INR'}).format(Number(value||0))},date(value){return value?new Date(value).toLocaleString():'—'},async mutate(action,message){if(this.busy)return;this.busy=true;this.error='';this.success='';try{await action();await this.load();this.success=message;this.$store.dispatch('session/restore',{force:true})}catch(e){this.error=errorMessage(e)}finally{this.busy=false}},async create(){const body={...this.draft};if(this.section==='viewings'&&body.slot)body.slot=new Date(body.slot).toISOString();await this.mutate(()=>api.createRental(this.section,body),'Workflow created.')},async saveSchedule(){const body={...this.schedule,amount:Number(this.schedule.amount),dueDay:Number(this.schedule.dueDay),endPeriod:this.schedule.endPeriod||null};await this.mutate(()=>api.saveRentSchedule(null,body),'Rent schedule saved.')},async generate(){await this.mutate(()=>api.generateRent(this.period),'Rent generation completed.')},async toggleSchedule(row){await this.mutate(()=>api.saveRentSchedule(row.id,{active:!row.active,version:row.version}),'Rent schedule updated.')},async selectPayment(row){this.selectedPayment=row;try{this.receipts=await api.rentReceipts(row.id);this.reconciliation=Object.fromEntries(this.receipts.map(r=>[r.id,{reference:r.reference,amount:String(r.amount)}]))}catch(e){this.error=errorMessage(e)}},async recordReceipt(){const id=this.selectedPayment.id;await this.mutate(()=>api.recordRentReceipt(id,{...this.receipt,amount:Number(this.receipt.amount),version:this.selectedPayment.version}),'Receipt recorded.');if(!this.error){this.receipt={amount:'',reference:'',receivedAt:today()};const latest=this.items.find(row=>row.id===id);if(latest)await this.selectPayment(latest)}},async reconcile(r){const id=this.selectedPayment.id,statement=this.reconciliation[r.id];await this.mutate(()=>api.reconcileRentReceipt(id,r.id,{version:this.selectedPayment.version,statementReference:statement.reference,statementAmount:Number(statement.amount)}),'Receipt reconciled.');if(!this.error){const latest=this.items.find(row=>row.id===id);if(latest)await this.selectPayment(latest)}},async updateMaintenance(row,changes){await this.mutate(()=>api.updateRental('maintenance',row.id,{...changes,version:row.version}),'Maintenance request updated.')},async addProgress(row){if(!this.progressNotes[row.id])return;await this.mutate(()=>api.addMaintenanceProgress(row.id,{note:this.progressNotes[row.id],version:row.version}),'Progress update added.')},async loadProgress(row){try{this.progress[row.id]=await api.maintenanceProgress(row.id)}catch(e){this.error=errorMessage(e)}},async updateLease(row,changes){await this.mutate(()=>api.updateRental('leases',row.id,{...changes,version:row.version}),'Lease workflow updated.')},async tenantResponse(row,status){await this.mutate(()=>api.updateRental('leases',row.id,{status,version:row.version,tenantResponseNotes:this.tenantNotes[row.id]||''}),'Tenant response saved.')},async startMoveoutAfterDecline(row){const moveOutDate=this.moveOutDates[row.id];if(!moveOutDate){this.error='Choose a planned move-out date.';return}await this.updateLease(row,{status:'MOVE_OUT_STARTED',moveOutDate})},async finalizeRenewal(row){await this.updateLease(row,{status:'RENEWED'})},async finalizeMoveOut(row){const f=this.leaseFinalize[row.id];await this.updateLease(row,{status:'COMPLETED',...f,depositSettlementAmount:Number(f.depositSettlementAmount)})},async viewingAction(row,action,body){await this.mutate(()=>api.viewingAction(row.id,action,body),'Viewing updated.')},startCancel(row){this.cancelledId=row.id;this.reschedulingId=null;this.cancelReasons[row.id]=''},async confirmCancel(row){const reason=(this.cancelReasons[row.id]||'').trim();if(!reason){this.error='Enter a cancellation reason.';return}await this.viewingAction(row,'cancel',{version:row.version,reason});if(!this.error)this.cancelledId=null},startReschedule(row){this.reschedulingId=row.id;this.cancelledId=null;this.reschedules[row.id]={slot:new Date(row.details.slot).toISOString().slice(0,16),reason:''}},async confirmReschedule(row){const form=this.reschedules[row.id];if(!form||!form.slot){this.error='Choose a new viewing time.';return}await this.viewingAction(row,'reschedule',{version:row.version,slot:new Date(form.slot).toISOString(),reason:form.reason||''});if(!this.error)this.reschedulingId=null}}};
</script>
